       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:vshulcz/deja-vu','deja-vu','vshulcz','https://github.com/vshulcz/deja-vu','vshulcz/deja-vu','','One memory shared by Claude Code, Codex, Cursor, Copilot CLI, OpenClaw and 20 more coding agents, built from the session history already on disk. A fix found in one agent comes back in any of them, including months of sessions from before you installed it. No LLM, no embeddings, one local Go binary.','',NULL,NULL,'dsh plugin add github:vshulcz/deja-vu','github',801,0,801000,'','2026-09-11','2026-09-11T07:44:11.040Z','2026-09-11T07:44:11.040Z',0,NULL,'1fd8ea6d')
