INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@goodandready/dsh-russian-lang','dsh-russian-lang','GooDAnDReaDY','https://github.com/GooDAnDReaDY/dsh-russian-lang','GooDAnDReaDY/dsh-russian-lang','ui','Adds Russian as the third option in the native Settings - General - Language menu of the DeepSeek Harness web UI, with 100% coverage of the 30 DSH core namespaces (722 keys) plus 9 plugin namespaces (962 keys). The locale runtime snapshot is extended at runtime on unpatched cores; no files in the DSH installation are modified, and the choice is persisted through the plugin-owned russian-lang settings namespace.','将俄语作为第三个选项添加到 DeepSeek Harness 网页 UI 原生的「设置 - 通用 - 语言」菜单中，覆盖 30 个 DSH 核心命名空间（722 个键，覆盖率 100%）以及 9 个插件命名空间（962 个键）。在未打补丁的核心上，运行时直接扩展 locale runtime snapshot；不会修改 DSH 安装目录中的任何文件，所选语言会通过插件自有的 russian-lang 命名空间持久化保存。','@goodandready/dsh-russian-lang',NULL,'dsh plugin --profile web add @goodandready/dsh-russian-lang','npm',8,5808,13808,'0.2.6','2026-08-26','2026-09-11T07:44:11.040Z','2026-09-11T07:44:11.040Z',0,NULL,'895f62d4')
