INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-checkpoint-diff','dsh-checkpoint-diff','tmpdot','https://github.com/tmpdot/dsh-checkpoint-diff','tmpdot/dsh-checkpoint-diff','session','Browses checkpoints produced by dsh-checkpoint-rewind as a timeline of time nodes and shows per-file line diffs between any two of them, with trace replay from session logs (no snapshot producer needed) and preview-first workspace rollback with single-shot undo, via /diff and /rollback commands, a JSON HTTP API, and a GUI panel.','把 dsh-checkpoint-rewind 产生的检查点变成时间线时间节点，任意两节点之间逐文件行级 diff；可从会话日志重放 trace 区间差异（无需快照生产者）；支持预览式工作区回滚与一次性撤销。提供 /diff、/rollback 命令、JSON HTTP API 与 GUI 面板。','dsh-checkpoint-diff',NULL,'dsh plugin --profile web add dsh-checkpoint-diff','npm',6,2358,8358,'0.5.2','2026-08-20','2026-09-11T07:44:11.040Z','2026-09-11T07:44:11.040Z',0,NULL,'6132db90')
