INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-wallpaper','dsh-wallpaper','codeMonkey-Pine','https://github.com/codeMonkey-Pine/dsh-wallpaper','codeMonkey-Pine/dsh-wallpaper','theme','Wallpaper Engine integration for the dsh web GUI: scan the local WE library (Steam workshop 431960 + local projects) and use its wallpapers as the page background — image/video/web rendered natively, scene wallpapers as softened static previews — with a 壁纸设计 panel (opacity, scope, fill, blur, vignette, fps, parallax, carousel, theme linkage) and agent tools wallpaper_scan/list/set/config.','Wallpaper Engine 壁纸联动：把本机下载的 WE 壁纸（创意工坊 431960 + 本地 projects）设为 DSH Web GUI 页面背景（图片/视频/网页原样渲染，场景壁纸柔化为静态预览），侧边栏「壁纸设计」面板可调不透明度、作用范围、填充、模糊、暗角、帧率、视差、轮播与主题联动，附 wallpaper_scan/list/set/config 四个 agent 工具。','dsh-wallpaper',NULL,'dsh plugin --profile web add dsh-wallpaper','npm',7,1345,8345,'0.1.3','2026-08-19','2026-09-11T07:44:11.040Z','2026-09-11T07:44:11.040Z',0,NULL,'b658c9f3')
