       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-usage-statistics-panel','dsh-usage-statistics-panel','HaoyueQin','https://github.com/HaoyueQin/dsh-usage-statistics-panel','HaoyueQin/dsh-usage-statistics-panel','usage','Usage statistics settings panel: 26-week activity heatmap, daily token trend with a cache hit-rate curve, per-model donut and breakdown, time-range filters, summary cards, one-time historical backfill and lossless rebuild.','用量统计设置面板：26 周活跃热力图、按日 Token 趋势与缓存命中率曲线、模型用量环形图与明细、时间范围筛选、汇总卡片，支持历史会话回扫与无损重建。','dsh-usage-statistics-panel',NULL,'dsh plugin --profile web add dsh-usage-statistics-panel','npm',6,2274,8274,'0.1.11','2026-08-23','2026-09-11T07:44:11.040Z','2026-09-11T07:44:11.040Z',0,NULL,'33b4fa53')
