INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@240xu/dsh-websearch','dsh-websearch','240xu','https://github.com/240xu/dsh-websearch','240xu/dsh-websearch','browser','Aggregated web search provider that fans one query out to 11 engines (Exa, Parallel, DuckDuckGo, SearXNG, Brave, Tavily, Serper, Mojeek, DeepSeek, Anthropic, OpenAI) concurrently, URL-dedupes and merges the results. Ships a settings card for toggling backends, storing API keys in the credential store, and tuning concurrency and timeouts.','聚合网络搜索插件：一次查询并发分发到 11 个引擎（Exa、Parallel、DuckDuckGo、SearXNG、Brave、Tavily、Serper、Mojeek、DeepSeek、Anthropic、OpenAI），URL 去重后合并结果。设置面板卡片可开关后端、将 API Key 存入凭证库，并调整并发与超时。','@240xu/dsh-websearch',NULL,'dsh plugin --profile web add @240xu/dsh-websearch','npm',2,2496,4496,'2.4.0','2026-08-24','2026-09-11T07:44:11.040Z','2026-09-11T07:44:11.040Z',0,NULL,'68de77c9')
