       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-review','dsh-review','Viger1','https://github.com/Viger1/dsh-review','Viger1/dsh-review','git','Adversarial code review — parallel finders inspect a diff through separate lenses (correctness, lifecycle, contract, security), then each finding goes to independent verifiers tasked with refuting it, and one refutation drops it.','对抗式代码审查：多个 finder 并行地从不同视角（正确性、生命周期、契约、安全）审查改动，随后每条发现都交给独立验证者去推翻它，只要有一票推翻就丢弃。','dsh-review',NULL,'dsh plugin --profile web add dsh-review','npm',1,1259,2259,'0.1.1','2026-08-18','2026-09-11T07:44:11.040Z','2026-09-11T07:44:11.040Z',0,NULL,'e1367219')
