INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-web-browse','dsh-web-browse','sweven-tears','https://github.com/sweven-tears/dsh-web-browse','sweven-tears/dsh-web-browse','dev','网页浏览 通用网页浏览器：侧边栏「网页浏览」按钮左键打开默认网页（DshDesktop 中为桌面网页标签页，Edge/Chrome 等通用浏览器中直接新开浏览器标签页），右键弹出悬浮搜索框（网址直接访问/文字用所选引擎搜索，确认后在新标签页打开）；页面选中文本后右键，原生右键菜单「复制」下方出现「🔍 搜索选中文本」项（DshDesktop 桌面端，点击即用选中文本打开悬浮搜索框）；extension/ 为 WebView2 扩展（仅 DshDesktop），向网页注入顶部地址/搜索栏；harness 设置新增「网页浏览设置」页，DshDesktop 中同步给桌面端。','网页浏览 通用网页浏览器：侧边栏「网页浏览」按钮左键打开默认网页（DshDesktop 中为桌面网页标签页，Edge/Chrome 等通用浏览器中直接新开浏览器标签页），右键弹出悬浮搜索框（网址直接访问/文字用所选引擎搜索，确认后在新标签页打开）；页面选中文本后右键，原生右键菜单「复制」下方出现「🔍 搜索选中文本」项（DshDesktop 桌面端，点击即用选中文本打开悬浮搜索框）；extension/ 为 WebView2 扩展（仅 DshDesktop），向网页注入顶部地址/搜索栏；harness 设置新增「网页浏览设置」页，DshDesktop 中同步给桌面端。','dsh-web-browse',NULL,'dsh plugin --profile web add github:sweven-tears/dsh-web-browse','github',0,0,0,'0.1.0','2026-08-16','2026-09-11T07:44:11.040Z','2026-09-11T07:44:11.040Z',0,NULL,'b33fcfbb')
